// ===== p92 : modèles Kenney (CC0) dans la vue personnage — palmiers et arbres, buissons, herbes, rochers, feu de camp, nattes, seau, bois =====
// Kenney Nature Kit et Survival Kit, licence CC0 (domaine public). Les modèles sont légers (quelques Ko chacun).
const KN92={"tree_palm": "", "tree_palmBend": "", "tree_detailed": "", "tree_oak_dark": "", "tree_default": "", "plant_bushDetailed": "", "plant_bushLarge": "", "grass_large": "", "rock_tallB": "", "rock_largeB": "", "stump_old": "", "log_large": "", "campfire_stones": "", "canoe": "", "s_campfire-pit": "", "s_bedroll": "", "s_bucket": "", "s_resource-wood": "", "s_tool-axe": "", "s_barrel": ""};
const KCM92='data:image/png;base64,';
const KM92={};let KM92ok=0;
(function(){const go=()=>{if(!window.THREE||!THREE.GLTFLoader){setTimeout(go,800);return}const man=new THREE.LoadingManager();man.setURLModifier(u=>/colormap\.png/.test(u)?KCM92:u);const L=new THREE.GLTFLoader(man);const ks=Object.keys(KN92);let n=0;
 ks.forEach(k=>{const bin=atob(KN92[k]),a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);try{L.parse(a.buffer,'',g=>{KM92[k]=g.scene;if(++n===ks.length)KM92ok=1},()=>{if(++n===ks.length)KM92ok=1})}catch(e){if(++n===ks.length)KM92ok=1}})};go()})();
// un modèle → des maillages instanciés, mis à l'échelle sur une hauteur voulue
function km92Parts(k){const s=KM92[k];if(!s)return null;s.updateMatrixWorld(true);const P=[];s.traverse(o=>{if(o.isMesh)P.push({g:o.geometry,m:o.material,w:o.matrixWorld.clone()})});const b=new THREE.Box3().setFromObject(s);return {P,h:Math.max(.01,b.max.y-b.min.y),y0:b.min.y}}
function km92Inst(V,k,L,haut){const D=km92Parts(k);if(!D||!L.length)return;const M=new THREE.Matrix4(),Sc=new THREE.Matrix4();D.P.forEach(p=>{const I=new THREE.InstancedMesh(p.g,p.m,L.length);L.forEach((q,i)=>{const s=(q.h||haut)/D.h;Sc.makeScale(s,s,s);M.makeRotationY(q.r||0).setPosition(q.x,q.y-D.y0*s,q.z);M.multiply(Sc).multiply(p.w);I.setMatrixAt(i,M)});I.instanceMatrix.needsUpdate=true;V.sc.add(I)})}
function km92Pose(V,k,x,z,haut,r){km92Inst(V,k,[{x,y:V.h(x,z),z,r:r||0,h:haut}],haut)}
function vpKenney(){const V=VP;if(!V||V.k92||!KM92ok||!V.p84)return;V.k92=1;const t=V.t,bas=(t.alt||0)<450;
 // 1. les arbres : on reprend les places des arbres simples, et l'on pose palmiers en bas, arbres de forêt en haut
 const tr=[],fe=[];V.sc.children.forEach(o=>{if(o.isInstancedMesh&&o.geometry.type==='CylinderGeometry')tr.push(o);if(o.isInstancedMesh&&o.geometry.type==='IcosahedronGeometry')fe.push(o)});
 const tronc=tr[0];if(tronc&&KM92.tree_detailed){const M=new THREE.Matrix4(),p=new THREE.Vector3(),q=new THREE.Quaternion(),s=new THREE.Vector3(),G={};
  for(let i=0;i<tronc.count;i++){tronc.getMatrixAt(i,M);M.decompose(p,q,s);const k=bas?(i%3===0?'tree_palmBend':i%3===1?'tree_palm':'tree_detailed'):(['tree_detailed','tree_oak_dark','tree_default','tree_detailed'][i%4]);(G[k]=G[k]||[]).push({x:p.x,y:p.y,z:p.z,r:i*1.7,h:Math.max(3,s.y*1.9)})}
  Object.keys(G).forEach(k=>km92Inst(V,k,G[k]));tr.forEach(o=>o.visible=false);fe.forEach(o=>o.visible=false)}
 // 2. les buissons à baies et les rochers où l'on grimpe
 (V.cueil||[]).forEach(c=>{if(c.k!=='baies')return;const b=c.g.children[0];if(b)b.visible=false;km92Pose(V,'plant_bushDetailed',c.x,c.z,1.3,c.x)});
 (V.roc||[]).forEach(r=>{V.sc.children.forEach(o=>{if(o.isMesh&&o.geometry.type==='DodecahedronGeometry'&&Math.hypot(o.position.x-r.x,o.position.z-r.z)<.5)o.visible=false});km92Pose(V,'rock_tallB',r.x,r.z,r.ht+.4,r.x)});
 // 3. des herbes et quelques souches, troncs couchés et rochers bas, un peu partout
 const H=[],So=[],Lg=[],Rk=[];for(let i=0;i<90;i++){const x=(Math.random()-.5)*150,z=(Math.random()-.5)*150;if(Math.hypot(x,z+30)<9)continue;H.push({x,y:V.h(x,z),z,r:Math.random()*6,h:.5+Math.random()*.4})}
 for(let i=0;i<14;i++){const x=(Math.random()-.5)*140,z=(Math.random()-.5)*140;if(Math.hypot(x,z+30)<12)continue;const o={x,y:V.h(x,z),z,r:Math.random()*6};(i%3===0?So:i%3===1?Lg:Rk).push(o)}
 km92Inst(V,'grass_large',H);km92Inst(V,'stump_old',So,.7);km92Inst(V,'log_large',Lg,.6);km92Inst(V,'rock_largeB',Rk,1.1);
 // 4. la vie du camp, ou le bivouac
 if(VPLIEU&&VPLIEU.g){km92Pose(V,'campfire_stones',2,-17,.6);km92Pose(V,'s_bedroll',4,-15,.25,1);km92Pose(V,'s_bedroll',0,-15,.25,2)}
 else{km92Pose(V,'s_campfire-pit',0,-30,.8);km92Pose(V,'s_bucket',2.6,-26.4,.5);km92Pose(V,'s_resource-wood',-14,-23,.6);km92Pose(V,'s_tool-axe',-13.2,-24.2,.4,.8);km92Pose(V,'s_barrel',3.4,-27.2,.9);
  for(let i=0;i<6;i++){const a=i/6*6.28;km92Pose(V,'s_bedroll',Math.cos(a)*6.5,-30+Math.sin(a)*4.5,.22,a)}
  if(bas)km92Pose(V,'canoe',-18,-40,.5,.6)}}
{const vb=vpBoucle;vpBoucle=function(){vb.apply(this,arguments);try{if(VP&&VP.p84&&!VP.k92&&KM92ok)vpKenney()}catch(e){console.warn('kenney',e)}}}
